import{_ as t,o as a,c as s,a2 as i}from"./chunks/framework.DncwoWA8.js";const u=JSON.parse('{"title":"Your first useful request","description":"","frontmatter":{},"headers":[],"relativePath":"guide/first-use.md","filePath":"guide/first-use.md"}'),o={name:"guide/first-use.md"};function n(r,e,l,c,d,h){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="your-first-useful-request" tabindex="-1">Your first useful request <a class="header-anchor" href="#your-first-useful-request" aria-label="Permalink to &quot;Your first useful request&quot;">​</a></h1><p>Start with a read-only task. This checks that you can find the right guidance without turning your first exercise into a repository change.</p><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><p>Complete the <a href="/projects/ai-skills/guide/install.html">reviewed installation</a> and open the harness in its reported workspace. For this exercise, select <code>asd-ste100-technical</code> if it fits the project, and confirm that the harness can discover its installed instructions. You also need a short technical explanation or a project procedure to review.</p><p>Do not install another skill automatically if the exercise&#39;s guidance is absent. Return to the approved setup process.</p><h2 id="choose-how-a-skill-starts" tabindex="-1">Choose how a skill starts <a class="header-anchor" href="#choose-how-a-skill-starts" aria-label="Permalink to &quot;Choose how a skill starts&quot;">​</a></h2><p>Human-selected workflows use <code>disable-model-invocation: true</code>. In Pi, their descriptions are hidden from automatic model selection, but their explicit commands still work. For example:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span>/skill:research Investigate this question and report the evidence. Do not implement changes.</span></span></code></pre></div><p>Guidance and safeguard skills omit that property. Pi advertises their descriptions so the model can select them when relevant; it loads their full instructions only when needed. You can also invoke these skills explicitly.</p><p>This setting controls selection, not permission. Workspace, delegation, mutation, and publication rules still apply. After changing skills in an existing Pi session, run <code>/reload</code>. Check invocation support separately in other harnesses.</p><h2 id="make-one-bounded-request" tabindex="-1">Make one bounded request <a class="header-anchor" href="#make-one-bounded-request" aria-label="Permalink to &quot;Make one bounded request&quot;">​</a></h2><p>Ask the agent in plain language:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span>Use asd-ste100-technical to review this procedure for a new developer.</span></span>
<span class="line"><span>Keep commands, identifiers, conditions, risks, and uncertainty unchanged.</span></span>
<span class="line"><span>Suggest a clearer version in the conversation. Do not edit files or run commands.</span></span></code></pre></div><p>Provide the text after that request. A named skill in a prompt is not a shell command or proof that the harness loaded it. Check the harness&#39;s resource view or the agent&#39;s explicit source acknowledgement.</p><h2 id="check-the-result" tabindex="-1">Check the result <a class="header-anchor" href="#check-the-result" aria-label="Permalink to &quot;Check the result&quot;">​</a></h2><p>You should get a clearer draft that keeps the technical meaning. Check that it:</p><ul><li>States prerequisites before the action that needs them.</li><li>Uses exact commands and stable terminology.</li><li>Preserves warnings, constraints, and unknowns.</li><li>Does not claim an unexecuted command passed.</li><li>Does not change repository files or start a later phase.</li></ul><p>If the draft invents facts or drops a condition, ask for a correction against the original text. A readable answer alone does not prove factual accuracy or model compliance.</p><h2 id="choose-a-next-step-only-if-needed" tabindex="-1">Choose a next step only if needed <a class="header-anchor" href="#choose-a-next-step-only-if-needed" aria-label="Permalink to &quot;Choose a next step only if needed&quot;">​</a></h2><ul><li>Need to update a real developer task? Try <a href="/projects/ai-skills/workflows/maintain-task-based-docs.html">maintain task-based docs</a> under the project&#39;s write rules.</li><li>Need evidence instead of an editing pass? Try <a href="/projects/ai-skills/workflows/research-a-decision.html">research a decision</a>, resolving its required <code>grilling</code> instructions first.</li><li>Already have approved code work? Try <a href="/projects/ai-skills/workflows/implement-a-small-change.html">implement a small change</a>.</li></ul><p>Stopping after the read-only exercise is a complete outcome. Installation checks, this agent walkthrough, and actual human usability testing are different kinds of evidence.</p>`,21)])])}const m=t(o,[["render",n]]);export{u as __pageData,m as default};
